toad_implementation.code_blueprint:
canvas {
  size: 700px 850px;
  fill: #EAE3D2;
  font-family: "Courier Prime, monospace";
}

>polaroidWhite = #FDFBF7;
>lightLeak = #E08968;
>inkBlack = #383635;
>seaGreen = #82A3A1;

rect #polaroidFrame {
  at: center of canvas;
  size: 480px 580px;
  fill: >polaroidWhite;
  radius: 4px;
}

rect #photoSquare {
  at: top center of #polaroidFrame offset 0px 32px;
  size: 416px 416px;
  fill: #4A3E3D;
}

rect #lightLeakSimulation {
  at: top right of #photoSquare;
  size: 140px 416px;
  fill: alpha(>lightLeak, 0.35);
}

text #markerNote {
  at: bottom center of #polaroidFrame offset 0px -40px;
  content: "Catania, August 1994  ★";
  font-size: 20px;
  font-weight: 700;
  color: >inkBlack;
}
